/* Lot 97: animated and transitioned registered properties in the reader sheet (generated by scripts/lot97_animgen.py; expectations from scripts/lot97_animmodel.py). */
#include "../../framework/unity.h"
#include <string.h>
#include <stdio.h>
#include "wf_sitecss.h"

static wf_site_t g_d;
static char g_html[4096];

static void prep(const char *css, int ms) {
    wf_site_set_time(ms);
    snprintf(g_html, sizeof(g_html), "<html><head><style>%s</style></head><body>"
             "<div id=o><p id=i>i</p></div><p id=q>q</p></body></html>", css);
    TEST_ASSERT_EQUAL(0, wf_site_prepare_ext(&g_d, g_html, (int)strlen(g_html), 640, 480, 0, 0));
    wf_site_set_time(0);
    TEST_ASSERT_EQUAL(1, g_d.nprops);
}

static const char *nv(const char *id) {
    int i;
    for (i = 0; i < g_d.nnodes; i++)
        if (!strcmp(g_d.node[i].id, id)) { const char *v = wf_site_node_var(&g_d, i, "--p"); return v ? v : "(none)"; }
    return "(no node)";
}

static void test_l97_sheet_0(void) {
    prep("@property --p { syntax: '<length>'; inherits: true; initial-value: 42px } #o { --p: 297px; transition: --p 400ms steps(3, jump-both) allow-discrete } @starting-style { #o { --p: 0px } }", 78);
    TEST_ASSERT_EQUAL_STRING("74.25px", nv("o"));
    TEST_ASSERT_EQUAL_STRING("74.25px", nv("i"));
    TEST_ASSERT_EQUAL(1, g_d.prop_animated + g_d.prop_transitioned > 0);
    prep("@property --p { syntax: '<custom-ident>'; inherits: false; initial-value: beta } @keyframes k { 25% { --p: beta } 50% { --p: gamma } to { --p: alpha } } #o { animation: k 500ms steps(4) 2 alternate }", 550);
    TEST_ASSERT_EQUAL_STRING("alpha", nv("o"));
    TEST_ASSERT_EQUAL_STRING("beta", nv("i"));
    TEST_ASSERT_EQUAL(1, g_d.prop_animated + g_d.prop_transitioned > 0);
    prep("@property --p { syntax: '<custom-ident>'; inherits: true; initial-value: alpha } @keyframes k { 33.33% { --p: beta } 60% { --p: alpha } } #o { animation: k 500ms ease-in-out -400ms infinite alternate; --p: beta }", 1761);
    TEST_ASSERT_EQUAL_STRING("beta", nv("o"));
    TEST_ASSERT_EQUAL_STRING("beta", nv("i"));
    TEST_ASSERT_EQUAL(1, g_d.prop_animated + g_d.prop_transitioned > 0);
    prep("@property --p { syntax: '<custom-ident>'; inherits: false; initial-value: beta } @keyframes k { 50% { --p: alpha } } #o { animation: k 1000ms cubic-bezier(0.1, 0.7, 1, 0.1) both }", 712);
    TEST_ASSERT_EQUAL_STRING("alpha", nv("o"));
    TEST_ASSERT_EQUAL_STRING("beta", nv("i"));
    TEST_ASSERT_EQUAL(1, g_d.prop_animated + g_d.prop_transitioned > 0);
}

